{
  "packet_id": "H6-T04-1",
  "claim_id": "C012",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C012.component",
    "value": "Accounts whose roster dates are unknown should have a fixed maximum follow-up.",
    "scope": "Conditional on an unknown roster date; the maximum duration is unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly supplies the unknown-date condition and fixed maximum follow-up rule."
    }
  },
  "signal_basis": {
    "component_id": "C012.signal_basis",
    "value": "Observation ends at declared follow-up limits, with unfinished trajectories marked as censored and accounts with no return or incomplete follow-up reported alongside published accounts.",
    "scope": "A fixed maximum applies when the roster date is unknown; reaching that limit does not establish abandonment or absence of benefit.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
          "source_id": "P013",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
