        },
        {
          "source_id": "P024",
          "role": "SUPPORT"
        },
        {
          "source_id": "P028",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the observation boundary, censoring and reporting requirements, and limits on interpreting incomplete trajectories."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C012.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported as a bounded observation rule without requiring an unresolved empirical relation."
    }
  },
  "rationale": "An unknown roster date cannot anchor roster-relative follow-up. A fixed maximum supplies an executable observation boundary, while censoring preserves the distinction between observation ending and an account reaching an outcome. This licenses the stated procedural rule within its limits.",
  "uncertainty": "The mapping does not establish an optimal maximum duration or guarantee that outcomes will be resolved by that time; neither is claimed.",
  "anomalies": []
}
